grant create on schema api,app_private,finance_private to git_tutor_commands;
create table finance_private.statement_imports(id uuid primary key default gen_random_uuid(),file_id uuid not null references app_private.files(id),receiving_account_id uuid not null references finance_private.receiving_accounts(id),receiving_account_version_id uuid not null references finance_private.receiving_account_versions(id),channel text not null check(channel in('instapay','vodafone_cash')),statement_period jsonb not null,created_by uuid not null references app_private.accounts(id),state text not null default 'pending' check(state in('pending','processing','completed','requires_manual_review','awaiting_file_bytes','failed','unknown')),accepted_count integer not null default 0,rejected_count integer not null default 0,failure_code text,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table finance_private.statement_import_runs(id uuid primary key default gen_random_uuid(),import_id uuid not null references finance_private.statement_imports(id),job_id uuid not null unique references app_private.outbox_jobs(id),idempotency_key text not null unique,prepared_version integer not null,request_hash text,result jsonb,started_at timestamptz not null default now(),completed_at timestamptz);
create table finance_private.statement_import_candidates(id uuid primary key default gen_random_uuid(),import_id uuid not null references finance_private.statement_imports(id),run_id uuid not null references finance_private.statement_import_runs(id),transfer_id uuid not null references finance_private.incoming_transfers(id),was_duplicate boolean not null,created_at timestamptz not null default now(),unique(run_id,transfer_id));
create function app_private.statement_import_immutable() returns trigger language plpgsql set search_path='' as $$
declare allowed text[];begin if tg_op='DELETE' then raise exception 'IMMUTABLE_VERSION';end if;allowed:=case tg_table_name when 'statement_imports' then array['state','accepted_count','rejected_count','failure_code','version','updated_at'] when 'statement_import_runs' then array['request_hash','result','completed_at'] else '{}'::text[] end;if(to_jsonb(old)-allowed) is distinct from(to_jsonb(new)-allowed) or(tg_table_name='statement_import_runs' and to_jsonb(old)->>'completed_at' is not null) then raise exception 'IMMUTABLE_VERSION';end if;return new;end $$;
create function api.create_statement_import(p_file_id uuid,p_receiving_account_id uuid,p_channel text,p_statement_period jsonb,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();context jsonb;account finance_private.receiving_accounts%rowtype;imported finance_private.statement_imports%rowtype;job uuid;date_from date;date_to date;begin
 perform app_private.payment_current_staff(actor);context:=app_private.booking_begin(actor,'create_statement_import',jsonb_build_object('file_id',p_file_id,'receiving_account_id',p_receiving_account_id,'channel',p_channel,'statement_period',p_statement_period),p_idempotency_key);if context->'replay_result'<>'null'::jsonb then return context->'replay_result';end if;
 select * into account from finance_private.receiving_accounts where id=p_receiving_account_id;if account.id is null then raise exception 'NOT_FOUND';end if;if not account.enabled or account.current_version_id is null then raise exception 'DESTINATION_UNVERIFIED';end if;if account.channel is distinct from p_channel then raise exception 'VALIDATION_ERROR';end if;
 perform app_private.payment_assert_file(p_file_id,'statement','receiving_account',account.id);
 if jsonb_typeof(p_statement_period) is distinct from 'object' or p_statement_period-array['from','to']<>'{}'::jsonb or jsonb_typeof(p_statement_period->'from') is distinct from 'string' or jsonb_typeof(p_statement_period->'to') is distinct from 'string' or p_statement_period->>'from'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or p_statement_period->>'to'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'VALIDATION_ERROR';end if;
 date_from:=(p_statement_period->>'from')::date;date_to:=(p_statement_period->>'to')::date;if date_from>date_to or date_from<date '0001-01-01' then raise exception 'VALIDATION_ERROR';end if;
 insert into finance_private.statement_imports(file_id,receiving_account_id,receiving_account_version_id,channel,statement_period,created_by) values(p_file_id,account.id,account.current_version_id,account.channel,p_statement_period,actor) returning * into imported;
 job:=app_private.enqueue_event(gen_random_uuid(),'statement_import_requested',imported.id,jsonb_build_object('import_id',imported.id),'payments.validate_statement');perform set_config('response.status','202',true);
 return app_private.booking_finish(context,imported.id,imported.version,jsonb_build_object('import_id',imported.id,'validation_job_id',job),'statement_import_created',jsonb_build_object('import_id',imported.id));
exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format then raise exception 'VALIDATION_ERROR';end $$;
create function app_private.prepare_statement_import(p_import_id uuid,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare imported finance_private.statement_imports%rowtype;run finance_private.statement_import_runs%rowtype;file app_private.files%rowtype;job uuid;begin
 if p_idempotency_key!~'^statement-import:[0-9a-f-]{36}$' then raise exception 'VALIDATION_ERROR';end if;job:=split_part(p_idempotency_key,':',2)::uuid;
 if not exists(select 1 from app_private.outbox_jobs j join app_private.domain_events e on e.id=j.event_id where j.id=job and j.purpose='payments.validate_statement' and e.event_type='statement_import_requested' and e.aggregate_id=p_import_id and e.payload=jsonb_build_object('import_id',p_import_id)) then raise exception 'FORBIDDEN';end if;
 select * into imported from finance_private.statement_imports where id=p_import_id for update;if imported.id is null then raise exception 'NOT_FOUND';end if;
 select * into run from finance_private.statement_import_runs where idempotency_key=p_idempotency_key;if run.id is not null and run.import_id<>imported.id then raise exception 'IDEMPOTENCY_CONFLICT';end if;
 file:=app_private.payment_assert_file(imported.file_id,'statement','receiving_account',imported.receiving_account_id);
 if run.id is null then
  update finance_private.statement_imports set state='processing',version=version+1,updated_at=now() where id=imported.id returning * into imported;
  insert into finance_private.statement_import_runs(import_id,job_id,idempotency_key,prepared_version) values(imported.id,job,p_idempotency_key,imported.version) returning * into run;
 end if;
 return jsonb_build_object('import_id',imported.id,'version',run.prepared_version,'state',imported.state,'file',jsonb_build_object('file_id',file.id,'object_key',file.object_key,'object_version',file.object_version,'checksum_sha256',file.checksum_sha256,'detected_mime',file.detected_mime,'byte_size',file.byte_size,'source_provenance',file.source_provenance),'receiving_account_id',imported.receiving_account_id,'channel',imported.channel,'statement_period',imported.statement_period,'completed_result',run.result);
end $$;
create function app_private.finalize_statement_import(p_import_id uuid,p_expected_version integer,p_checksum_sha256 text,p_state text,p_candidates jsonb,p_reason_code text,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare imported finance_private.statement_imports%rowtype;run finance_private.statement_import_runs%rowtype;file app_private.files%rowtype;item jsonb;amount bigint;observed timestamptz;business_date date;refs text[]:='{}';t finance_private.incoming_transfers%rowtype;created integer:=0;duplicates integer:=0;digest text;result jsonb;begin
 select * into imported from finance_private.statement_imports where id=p_import_id;if imported.id is null then raise exception 'NOT_FOUND';end if;
 perform 1 from finance_private.receiving_accounts where id=imported.receiving_account_id for update;
 select * into imported from finance_private.statement_imports where id=imported.id for update;select * into run from finance_private.statement_import_runs where idempotency_key=p_idempotency_key and import_id=imported.id for update;
 if run.id is null then raise exception 'FORBIDDEN';end if;
 digest:=app_private.catalog_hash(jsonb_build_object('import_id',p_import_id,'expected_version',p_expected_version,'checksum_sha256',p_checksum_sha256,'state',p_state,'candidates',p_candidates,'reason_code',p_reason_code));
 if run.result is not null then if run.request_hash<>digest then raise exception 'IDEMPOTENCY_CONFLICT';end if;return run.result;end if;
 if imported.version<>p_expected_version or run.prepared_version<>p_expected_version then raise exception 'VERSION_CONFLICT';end if;
 file:=app_private.payment_assert_file(imported.file_id,'statement','receiving_account',imported.receiving_account_id);
 if p_checksum_sha256 is distinct from file.checksum_sha256 or p_state is null or p_state not in('completed','requires_manual_review','awaiting_file_bytes','failed','unknown') or jsonb_typeof(p_candidates) is distinct from 'array' or jsonb_array_length(p_candidates)>10000 then raise exception 'VALIDATION_ERROR';end if;
 if p_state='completed' then
  if p_reason_code is not null or file.detected_mime not in('text/csv','application/csv') then raise exception 'VALIDATION_ERROR';end if;
  -- Entire batch first. A malformed direct worker call cannot partially insert candidates.
  for item in select value from jsonb_array_elements(p_candidates) loop
   if jsonb_typeof(item) is distinct from 'object' or item-array['external_id','amount_minor','currency','observed_at']<>'{}'::jsonb or jsonb_typeof(item->'external_id') is distinct from 'string' or length(btrim(item->>'external_id')) not between 1 and 200 or item->>'currency' is distinct from 'EGP' or jsonb_typeof(item->'observed_at') is distinct from 'string' then raise exception 'VALIDATION_ERROR';end if;
   amount:=app_private.package_safe_integer(item->'amount_minor',1);observed:=(item->>'observed_at')::timestamptz;
   if not isfinite(observed) or observed<timestamptz '0001-01-01 00:00:00+00' or observed>=timestamptz '10000-01-01 00:00:00+00' or observed>now() then raise exception 'INVALID_TIME';end if;
   business_date:=(observed at time zone 'Africa/Cairo')::date;if business_date<(imported.statement_period->>'from')::date or business_date>(imported.statement_period->>'to')::date then raise exception 'INVALID_TIME';end if;
   if btrim(item->>'external_id')=any(refs) then raise exception 'DUPLICATE_TRANSFER';end if;refs:=array_append(refs,btrim(item->>'external_id'));
   select * into t from finance_private.incoming_transfers where receiving_account_id=imported.receiving_account_id and channel=imported.channel and external_id=btrim(item->>'external_id');
   if t.id is not null and(t.amount_minor<>amount or t.currency<>item->>'currency' or t.observed_at<>observed) then p_state:='requires_manual_review';p_reason_code:='DUPLICATE_EXTERNAL_ID';exit;end if;
  end loop;
 else
  if jsonb_array_length(p_candidates)<>0 or p_reason_code is null or p_reason_code not in('PDF_REQUIRES_MANUAL_REVIEW','UNSUPPORTED_FILE_TYPE','INPUT_LIMIT_EXCEEDED','INVALID_UTF8','MALFORMED_CSV','HEADER_MISMATCH','INVALID_ROW','OUTSIDE_STATEMENT_PERIOD','DUPLICATE_EXTERNAL_ID','CHECKSUM_MISMATCH','FILE_SIZE_MISMATCH','FILE_BYTES_UNAVAILABLE','FILE_READ_FAILED') then raise exception 'VALIDATION_ERROR';end if;
  if(p_state='awaiting_file_bytes') is distinct from(p_reason_code='FILE_BYTES_UNAVAILABLE') or(p_state='failed') is distinct from(p_reason_code='FILE_READ_FAILED') then raise exception 'VALIDATION_ERROR';end if;
 end if;
 if p_state='completed' then
  for item in select value from jsonb_array_elements(p_candidates) loop
   select * into t from finance_private.incoming_transfers where receiving_account_id=imported.receiving_account_id and channel=imported.channel and external_id=btrim(item->>'external_id');
   if t.id is null then insert into finance_private.incoming_transfers(receiving_account_id,receiving_account_version_id,channel,external_id,amount_minor,currency,observed_at,statement_evidence_file_id,created_by) values(imported.receiving_account_id,imported.receiving_account_version_id,imported.channel,btrim(item->>'external_id'),(item->>'amount_minor')::bigint,'EGP',(item->>'observed_at')::timestamptz,file.id,imported.created_by) returning * into t;created:=created+1;
    insert into finance_private.statement_import_candidates(import_id,run_id,transfer_id,was_duplicate) values(imported.id,run.id,t.id,false);
   else duplicates:=duplicates+1;insert into finance_private.statement_import_candidates(import_id,run_id,transfer_id,was_duplicate) values(imported.id,run.id,t.id,true);end if;
  end loop;
 end if;
 result:=jsonb_build_object('state',p_state,'candidate_count',created,'duplicate_count',duplicates);
 update finance_private.statement_imports set state=p_state,accepted_count=created,rejected_count=case when p_state='completed' then 0 else jsonb_array_length(p_candidates) end,failure_code=p_reason_code,version=version+1,updated_at=now() where id=imported.id;
 update finance_private.statement_import_runs set request_hash=digest,result=result,completed_at=now() where id=run.id;
 insert into app_private.audit_events(actor_account_id,command_id,action,aggregate_id,details) values(null,run.id,'statement_import_validated',imported.id,result);
 return result;
end $$;
create function app_private.payment_import_dto(p_import_id uuid) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('import_id',id,'version',version,'receiving_account_id',receiving_account_id,'channel',channel,'state',state,'accepted_count',accepted_count,'rejected_count',rejected_count,'failure_code',failure_code,'created_at',created_at,'updated_at',updated_at) from finance_private.statement_imports where id=p_import_id$$;
create function api.list_statement_imports(p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();after_at timestamptz;after_id uuid;rows jsonb;begin perform app_private.payment_current_staff(actor);if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.payment_import_dto(x.id)) order by x.created_at desc,x.id desc),'[]') into rows from(select * from finance_private.statement_imports where p_cursor is null or(created_at,id)<(after_at,after_id) order by created_at desc,id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);end $$;
create function api.get_statement_import(p_import_id uuid,p_candidate_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();after_at timestamptz;after_id uuid;rows jsonb;result jsonb;begin perform app_private.payment_current_staff(actor);result:=app_private.payment_import_dto(p_import_id);if result is null then raise exception 'NOT_FOUND';end if;if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;if p_candidate_cursor is not null then if length(p_candidate_cursor)>200 or array_length(string_to_array(p_candidate_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_candidate_cursor,'|',1)::timestamptz;after_id:=split_part(p_candidate_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.payment_transfer_dto(x.transfer_id,actor,true)) order by x.created_at desc,x.id desc),'[]') into rows from(select * from finance_private.statement_import_candidates where import_id=p_import_id and(p_candidate_cursor is null or(created_at,id)<(after_at,after_id)) order by created_at desc,id desc limit p_limit+1)x;return result||jsonb_build_object('candidate_page',app_private.package_page(rows,p_limit));end $$;
do $$declare name text;f record;begin foreach name in array array['statement_imports','statement_import_runs','statement_import_candidates'] loop execute format('alter table finance_private.%I enable row level security',name);execute format('create policy commands_access on finance_private.%I to git_tutor_commands using(true) with check(true)',name);execute format('grant select,insert on finance_private.%I to git_tutor_commands',name);execute format('revoke all on finance_private.%I from public,anon,authenticated,service_role,git_tutor_worker',name);execute format('create trigger immutable_statement_source before update or delete on finance_private.%I for each row execute function app_private.statement_import_immutable()',name);end loop;
 grant update on finance_private.statement_imports,finance_private.statement_import_runs to git_tutor_commands;
 for f in select p.oid::regprocedure::text signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='app_private' and p.proname in('statement_import_immutable','prepare_statement_import','finalize_statement_import','payment_import_dto')) or(n.nspname='api' and p.proname in('create_statement_import','list_statement_imports','get_statement_import')) loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api' then execute format('grant execute on function %s to authenticated',f.signature);elsif f.proname in('prepare_statement_import','finalize_statement_import') then execute format('grant execute on function %s to git_tutor_worker',f.signature);end if;end loop;
end $$;
revoke create on schema api,app_private,finance_private from git_tutor_commands;
notify pgrst,'reload schema';

